package com.library.service.impl; import com.library.model.entity.Category; import com.library.mapper.CategoryMapper; import com.library.service.CategoryService; import org.springframework.stereotype.Service; import java.util.List;
@Service public class CategoryServiceImpl implements CategoryService { private final CategoryMapper mapper; public CategoryServiceImpl(CategoryMapper mapper){this.mapper=mapper;} public List<Category> list(){return mapper.list();} public void save(Category x){mapper.insert(x);} public void update(Category x){mapper.update(x);} public void delete(Long id){mapper.delete(id);} }
